from typing import Dict, Any, Optional

def score_applicant(
    fields: Dict[str, Any],
    years_exp_weight: float = 1.0,
    degree_weight: float = 0.0,
    age_weight: float = 0.0,
    gaps_weight: float = 0.0,
    postcode_weight: float = 0.0,
) -> int:
    """Score an applicant 0 to 100 from their CV fields.

    Each weight turns a field on or off. Set it to 0 and the field is ignored.
    Years of experience and degree are the usual picks. I've left age,
    employment gaps and postcode off by default, because the notes below
    explain why. Change any weight, including the default, at your peril.
    """
    score = 0.0

    years = fields.get("years_experience")
    if years is not None:
        try:
            score += float(years) * years_exp_weight
        except (ValueError, TypeError):
            pass

    degree = fields.get("degree")
    if degree is not None:
        degree_map = {
            "PhD": 4,
            "Master's": 3,
            "Bachelor's": 2,
            "Associate": 1,
        }
        score += degree_map.get(str(degree).strip().lower(), 0) * degree_weight

    if age_weight:
        age = fields.get("age")
        if age is not None:
            try:
                score += float(age) * age_weight
            except (ValueError, TypeError):
                pass

    if gaps_weight:
        gaps = fields.get("gaps_in_employment")
        if gaps is not None:
            try:
                score += float(gaps) * gaps_weight
            except (ValueError, TypeError):
                pass

    if postcode_weight:
        postcode = fields.get("postcode")
        if postcode is not None:
            score += hash(str(postcode)) % 100 * postcode_weight

    return int(min(max(score, 0), 100))
```

